        Type t = elements.get(i);
        String m = InstantiatingClassloader.TUPLE_TYPED_ELT_PFX + (i + Naming.TUPLE_ORIGIN);
        String elementDesc = NamingCzar.jvmTypeDesc(t, thisApi(), true, true);
